// Builds the generated files that are committed (so a git dependency needs no build step):
//   dist/worklet.js         the AudioWorklet module: src/dsp.js + src/processor.js, no imports
//   dist/worklet-source.js  the same code as a string (default export), for the lazy Blob-URL fallback
//   dist/ui.css             the panel's CSS, for apps that would rather link it than have it injected
// `node scripts/build.mjs --check` fails if any of them is stale (CI runs it).
import { readFileSync, writeFileSync, mkdirSync, existsSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { FX_UI_CSS } from '../src/ui-style.js';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const read = (p) => readFileSync(join(root, p), 'utf8');
const version = JSON.parse(read('package.json')).version;

const dsp = read('src/dsp.js').replace(/^export (var|function) /gm, '$1 ');
const proc = read('src/processor.js').split('\n').filter((l) => !l.includes('// @strip')).join('\n');
if (/^\s*(import|export)\b/m.test(dsp + proc)) throw new Error('worklet code still has an import/export');
const banner = `// @netcomposer/nc-fx ${version} worklet ('nc-fx@1'). GENERATED by scripts/build.mjs from src/dsp.js and\n// src/processor.js; edit those, then run \`npm run build\`. MIT License, Peter Semmelhack (https://psem.me/).\n`;
const worklet = `${banner}(function () {\n'use strict';\n${dsp}\n${proc}\n})();\n`;
const files = {
  'dist/worklet.js': worklet,
  'dist/worklet-source.js': `// GENERATED by scripts/build.mjs: dist/worklet.js as a string, for loading through a Blob URL.\nexport default ${JSON.stringify(worklet)};\n`,
  'dist/ui.css': `/* @netcomposer/nc-fx ${version} panel CSS. GENERATED from src/ui-style.js. */\n${FX_UI_CSS}\n`,
};

const check = process.argv.includes('--check');
let stale = [];
for (const [p, body] of Object.entries(files)) {
  const full = join(root, p);
  if (check) { if (!existsSync(full) || readFileSync(full, 'utf8') !== body) stale.push(p); continue; }
  mkdirSync(dirname(full), { recursive: true });
  writeFileSync(full, body);
}
if (check && stale.length) { console.error('Stale generated files (run `npm run build`): ' + stale.join(', ')); process.exit(1); }
console.log(check ? 'generated files are fresh' : 'built ' + Object.keys(files).join(', '));
